import{_ as e,o as t,a as i,b as r}from"./app.C41L12d5.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"TSCM输入的矩阵乘","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/tscm_input_matmul"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/tscm_input_matmul.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/tscm_input_matmul.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1786954352000}'),n={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/tscm_input_matmul.md"};function _(s,a,c,o,m,p){return t(),i("div",null,[...a[0]||(a[0]=[r(`<div><article class="markdown-body"><h1>TSCM输入的矩阵乘<span id="ZH-CN_TOPIC_0000002500468244"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002298654821_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>TSCM表示L1 Buffer空间对应的逻辑内存，L1 Buffer相关内容见<a href="../../../../programming_guide/advanced_programming/hardware_implementation/basic_architecture.html#section123639375417">存储单元</a>，开发者可以自行管理TSCM以高效利用硬件资源。比如，开发者可缓存一份TSCM数据，在不同使用场景中灵活配置为Matmul操作的A矩阵、B矩阵或Bias偏置矩阵，实现内存复用与计算效率优化。在TSCM输入场景，用户管理整块TSCM内存空间，Matmul直接使用传入的TSCM内存地址，不进行Global Memory到TSCM的数据搬入。</p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002298654821_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>用户需要自定义数据搬入到TSCM及自定义管理的场景，即需要自定义实现数据搬入功能，如非连续搬入或对搬入数据进行预处理等。用户通过自定义管理TSCM可灵活配置MTE2流水，实现跨Matmul对象的全局<a href="../../../../technical_appendix/concepts_and_terms/performance_optimization/double_buffer.html">DoubleBuffer</a>，MTE2相关内容见<a href="../../../../programming_guide/advanced_programming/hardware_implementation/basic_architecture.html#section123639375417">搬运单元</a>。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002298654821_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><p>设置为TSCM输入的矩阵必须在TSCM中全载，全载即全部的矩阵数据同时搬入及保持在TSCM中。</p><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002298654821_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_tscm">自定义数据来源为GM的TSCM输入的Matmul算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>TQue&lt;TPosition::A1, 1&gt; scm; // 队列逻辑位置A1，队列深度为1
pipe-&gt;InitBuffer(scm, 1, tiling.M * tiling.Ka * sizeof(A_T)); 
// A_TYPE的TPosition为TSCM， B_TYPE的TPosition为GM
Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE&gt; mm1;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm1);
mm1.Init(&amp;tiling);
// 自定义A矩阵GM到TSCM的搬运
auto scmTensor = scm.AllocTensor&lt;A_T&gt;();
DataCopy(scmTensor, gm_a, tiling.M * tiling.Ka);
scm.EnQue(scmTensor);
LocalTensor&lt;A_T&gt; scmLocal = scm.DeQue&lt;A_T&gt;();
// A矩阵设置为TSCM输入，B矩阵为GM输入
mm1.SetTensorA(scmLocal);
mm1.SetTensorB(gm_b);
mm1.SetBias(gm_bias);
mm1.IterateAll(gm_c);
scm.FreeTensor(scmLocal);
</code></pre></div></article></div>`,1)])])}const u=e(n,[["render",_]]);export{d as __pageData,u as default};
